#include <stdio.h>

typedef unsigned long Counter;          /* alias: same type. */

typedef struct Point {                  /* shorter name for a struct. */
    int x, y;
} Point;

typedef int (*Compare)(const void *, const void *);   /* function pointer type. */

/* Real distinction: wrap in a struct. */
typedef struct { double value; } Celsius;
typedef struct { double value; } Fahrenheit;
Celsius to_celsius(Fahrenheit f) { return (Celsius){(f.value - 32) * 5 / 9}; }

typedef char *String;
/* const String s;  means char *const s, not const char *s. */
typedef const char *ConstText;          /* put const inside the typedef instead. */

int main(void) {
    Counter visits = 0;
    unsigned long raw = visits;         /* no conversion needed: same type. */
    Point p = {.x = 1, .y = 2};
    Celsius c = to_celsius((Fahrenheit){212});   /* 100.0. */
    printf("%lu %d %.1f\n", raw, p.x, c.value);
    return 0;
}
